20	namespace vortex {
21	
22	// Pure RMW kernel for the RVA op set. Operates on word-level
23	// holders; `width` selects W (4 bytes) or D (8 bytes). Returns
24	// {new_word, ret_word}: `new_word` is what gets merged back into
25	// the line on a store-bearing op; `ret_word` is what rd should
26	// observe (sign-extended by the LSU response formatter).
27	//
28	// LR returns {old, old} (no store); SC's return is decided by the
29	// caller (using the reservation table) and does not flow through
30	// here.
31	struct AmoComputeResult {
32	  uint64_t new_word;
33	  uint64_t ret_word;
34	};
35	
36	inline AmoComputeResult amo_compute(MemOp op, uint8_t width,
37	                                    uint64_t old_word, uint64_t rhs,
38	                                    bool unsigned_minmax = false) {
39	  // Mask both inputs to width-sized values; sign-extension at the
40	  // word boundary is needed for signed comparisons (MIN/MAX).
41	  const bool is_w = (width == 2);
42	  auto mask_w = [](uint64_t v) { return v & 0xFFFFFFFFull; };
43	  auto sext_w = [](uint64_t v) -> int64_t {
44	    return (int64_t)(int32_t)(uint32_t)v;
45	  };
46	
47	  uint64_t a = is_w ? mask_w(old_word) : old_word;
48	  uint64_t b = is_w ? mask_w(rhs)      : rhs;
49	  int64_t  ai = is_w ? sext_w(old_word) : (int64_t)old_word;
50	  int64_t  bi = is_w ? sext_w(rhs)      : (int64_t)rhs;
51	
52	  uint64_t newv = a;
53	  switch (op) {
54	  case MemOp::AMO_LR:    /* no store */ newv = a; break;
55	  case MemOp::AMO_SC:    newv = b;                break;
56	  case MemOp::AMO_SWAP:  newv = b;                break;
57	  case MemOp::AMO_ADD:   newv = a + b;            break;
58	  case MemOp::AMO_AND:   newv = a & b;            break;
59	  case MemOp::AMO_OR:    newv = a | b;            break;
60	  case MemOp::AMO_XOR:   newv = a ^ b;            break;
61	  // MIN/MAX collapse signed/unsigned variants — flag picks compare style.
62	  case MemOp::AMO_MIN:   newv = unsigned_minmax ? ((a < b) ? a : b)
63	                                                : (uint64_t)((ai < bi) ? ai : bi); break;
64	  case MemOp::AMO_MAX:   newv = unsigned_minmax ? ((a > b) ? a : b)
65	                                                : (uint64_t)((ai > bi) ? ai : bi); break;
66	  default:
67	    std::abort();
68	  }
69	  if (is_w) newv = mask_w(newv);
70	
71	  // Return value: original loaded word (LSU sext at width when writing rd).
72	  uint64_t retv = is_w ? mask_w(old_word) : old_word;
73	  return {newv, retv};
74	}
