76	// Pack/unpack the active word inside a `mem_block_t` at byte_off,
77	// width 2 (4 bytes) or 3 (8 bytes).
78	inline uint64_t amo_load_word(const uint8_t* line, uint32_t byte_off, uint8_t width) {
79	  uint64_t v = 0;
80	  uint32_t n = 1u << width; // 4 or 8
81	  for (uint32_t i = 0; i < n; ++i) {
82	    v |= (uint64_t)line[byte_off + i] << (8 * i);
83	  }
84	  return v;
85	}
