88	  uint32_t n = 1u << width;
89	  for (uint32_t i = 0; i < n; ++i) {
90	    line[byte_off + i] = (uint8_t)((v >> (8 * i)) & 0xff);
91	  }
92	}
93	
94	inline uint64_t amo_byteen(uint32_t byte_off, uint8_t width) {
95	  uint32_t n = 1u << width;
96	  return ((1ull << n) - 1ull) << byte_off;
97	}
