1	#include <vx_spawn2.h>
2	#include <vx_intrinsics.h>
3	#include "common.h"
4	
5	// All harts contend on a single shared word. Each test exercises a
6	// different RVA primitive; the host validates the closed-form expected
7	// final value against the post-run shared word, plus per-hart "observed
8	// old value" / "iterations completed" counters where applicable.
9	
10	typedef void (*PFN_Kernel)(kernel_arg_t* __UNIFORM__ arg);
11	
12	// Globally-unique hart id (mhartid): (cid * NUM_WARPS + wid) * NUM_THREADS
13	// + tid, matching the LLC reservation table's make_hart_id.
14	static inline uint32_t hart_id() {
15	  return (uint32_t)vx_hart_id();
16	}
17	
18	// 1) AMOADD hammer.
19	//   each hart does N amoadd.w +1 → final = num_harts * iters.
20	void kernel_amoadd(kernel_arg_t* __UNIFORM__ arg) {
21	  auto shared = (int32_t*)arg->shared_addr;
22	  for (uint32_t i = 0; i < arg->iters; ++i) {
23	    __atomic_fetch_add(shared, 1, __ATOMIC_SEQ_CST);
24	  }
25	}
26	
27	// 2) AMOOR hammer.
28	//   each hart sets its own bit (mod 32). After all harts, every used
29	//   bit is set; verify final == ((1 << min(num_harts,32)) - 1) for ≤32
30	//   harts. With more harts, multiple harts share bits; final is just
31	//   any value with all those bits set (they're idempotent).
32	void kernel_amoor(kernel_arg_t* __UNIFORM__ arg) {
33	  auto shared = (uint32_t*)arg->shared_addr;
34	  uint32_t bit = 1u << (hart_id() & 31);
35	  for (uint32_t i = 0; i < arg->iters; ++i) {
36	    __atomic_fetch_or(shared, bit, __ATOMIC_SEQ_CST);
37	  }
38	}
39	
40	// 3) AMOAND hammer.
41	//   start with all bits set; each hart clears its own bit (mod 32).
42	//   For num_harts ≥ 32, final = 0; for fewer, final = ~mask of cleared bits.
43	void kernel_amoand(kernel_arg_t* __UNIFORM__ arg) {
44	  auto shared = (uint32_t*)arg->shared_addr;
45	  uint32_t bit = ~(1u << (hart_id() & 31));
46	  for (uint32_t i = 0; i < arg->iters; ++i) {
47	    __atomic_fetch_and(shared, bit, __ATOMIC_SEQ_CST);
48	  }
49	}
50	
51	// 4) AMOXOR hammer.
52	//   each hart XORs its bit twice (per iter). Net effect per iter = 0,
53	//   so final = initial value. Tests that XOR commit + return is sane
54	//   under contention even if final is invariant.
55	void kernel_amoxor(kernel_arg_t* __UNIFORM__ arg) {
56	  auto shared = (uint32_t*)arg->shared_addr;
57	  uint32_t bit = 1u << (hart_id() & 31);
58	  for (uint32_t i = 0; i < arg->iters; ++i) {
59	    __atomic_fetch_xor(shared, bit, __ATOMIC_SEQ_CST);
60	    __atomic_fetch_xor(shared, bit, __ATOMIC_SEQ_CST);
61	  }
62	}
63	
64	// 5) AMOMAX hammer (signed).
65	//   each hart amomax.w with its hart_id. Final = num_harts - 1.
66	void kernel_amomax(kernel_arg_t* __UNIFORM__ arg) {
67	  auto shared = (int32_t*)arg->shared_addr;
68	  int32_t hid = (int32_t)hart_id();
69	  for (uint32_t i = 0; i < arg->iters; ++i) {
70	    int32_t expected = __atomic_load_n(shared, __ATOMIC_SEQ_CST);
71	    int32_t prev;
72	    asm volatile ("amomax.w %0, %2, (%1)"
73	                  : "=r"(prev)
74	                  : "r"(shared), "r"(hid)
75	                  : "memory");
