80	// 6) AMOMINU hammer (unsigned).
81	//   start with shared = 0xFFFFFFFF; each hart amominu.w with its hart_id.
82	//   Final = 0 (lowest hart_id wins).
83	void kernel_amominu(kernel_arg_t* __UNIFORM__ arg) {
84	  auto shared = (uint32_t*)arg->shared_addr;
85	  uint32_t hid = hart_id();
86	  for (uint32_t i = 0; i < arg->iters; ++i) {
87	    uint32_t prev;
88	    asm volatile ("amominu.w %0, %2, (%1)"
89	                  : "=r"(prev)
90	                  : "r"(shared), "r"(hid)
91	                  : "memory");
