93	  }
94	}
95	
96	// 7) AMOSWAP exchange.
97	//   each hart swaps in its hart_id repeatedly. The host accepts any
98	//   final value that is a valid hart_id. Per-hart buffer captures each
99	//   hart's last observed-old value to verify it's a previously-written
100	//   hart_id (not garbage).
101	void kernel_amoswap(kernel_arg_t* __UNIFORM__ arg) {
102	  auto shared = (uint32_t*)arg->shared_addr;
103	  auto observed = (uint32_t*)arg->per_hart_addr;
104	  uint32_t hid = hart_id();
105	  uint32_t last_old = hid;
106	  for (uint32_t i = 0; i < arg->iters; ++i) {
107	    last_old = __atomic_exchange_n(shared, hid, __ATOMIC_SEQ_CST);
108	  }
109	  observed[hid] = last_old;
110	}
111	
112	// 8) LR/SC counter (lock-free CAS-style increment).
113	//   each hart increments shared by 1 via LR/SC retry. Final =
114	//   num_harts * iters. Per-hart buffer captures retry count.
115	void kernel_lrsc_counter(kernel_arg_t* __UNIFORM__ arg) {
116	  auto shared = (int32_t*)arg->shared_addr;
117	  auto retries = (uint32_t*)arg->per_hart_addr;
118	  uint32_t hid = hart_id();
119	  uint32_t r = 0;
120	  for (uint32_t i = 0; i < arg->iters; ++i) {
121	    int32_t old, sc_fail;
122	    do {
123	      asm volatile ("lr.w %0, (%1)"
124	                    : "=r"(old)
125	                    : "r"(shared)
126	                    : "memory");
127	      int32_t newv = old + 1;
128	      asm volatile ("sc.w %0, %2, (%1)"
129	                    : "=r"(sc_fail)
130	                    : "r"(shared), "r"(newv)
131	                    : "memory");
132	      if (sc_fail) ++r;
133	    } while (sc_fail);
134	  }
135	  retries[hid] = r;
136	}
137	
138	// 8) AMOADD.W.AQRL hammer.
139	//   Same closed-form as kernel_amoadd, but the AMO carries the
140	//   acquire+release ordering bits. SimX is sequentially consistent,
141	//   so the result must be identical to the plain variant — this test
142	//   verifies the .aqrl encoding decodes correctly and that the bank
143	//   commits the RMW the same way it does for plain AMOADD.
144	//   Final = num_harts * iters.
145	void kernel_amoadd_aqrl(kernel_arg_t* __UNIFORM__ arg) {
146	  auto shared = (int32_t*)arg->shared_addr;
147	  for (uint32_t i = 0; i < arg->iters; ++i) {
148	    int32_t one = 1;
149	    int32_t prev;
150	    asm volatile ("amoadd.w.aqrl %0, %2, (%1)"
151	                  : "=r"(prev)
152	                  : "r"(shared), "r"(one)
153	                  : "memory");
154	    (void)prev;
155	  }
156	}
157	
158	// 9) LR.W.AQ / SC.W.RL counter (canonical acquire/release idiom).
159	//   Same lock-free CAS retry as kernel_lrsc_counter, but with the
160	//   acquire bit on LR and the release bit on SC. Functionally
161	//   equivalent under SimX's SC ordering; verifies the .aq/.rl
162	//   encoding paths through decode and the bank.
163	//   Final = num_harts * iters.
164	void kernel_lrsc_counter_aqrl(kernel_arg_t* __UNIFORM__ arg) {
165	  auto shared = (int32_t*)arg->shared_addr;
166	  for (uint32_t i = 0; i < arg->iters; ++i) {
167	    int32_t old, sc_fail;
168	    do {
169	      asm volatile ("lr.w.aq %0, (%1)"
170	                    : "=r"(old)
171	                    : "r"(shared)
172	                    : "memory");
173	      int32_t newv = old + 1;
174	      asm volatile ("sc.w.rl %0, %2, (%1)"
175	                    : "=r"(sc_fail)
176	                    : "r"(shared), "r"(newv)
177	                    : "memory");
178	    } while (sc_fail);
179	  }
180	}
181	
182	// 10) Atomic reduction.
183	//   Every hart reads one element from per_hart[] and atomicAdds it
184	//   into the single global accumulator at shared_addr. Final =
185	//   sum_{h=0..n-1} per_hart[h]. With per_hart[h] = h+1 (set by host),
186	//   final = n*(n+1)/2.
187	void kernel_atomic_reduction(kernel_arg_t* __UNIFORM__ arg) {
188	  auto shared = (int32_t*)arg->shared_addr;
189	  auto in     = (int32_t*)arg->per_hart_addr;
190	  uint32_t hid = hart_id();
191	  __atomic_fetch_add(shared, in[hid], __ATOMIC_SEQ_CST);
192	}
193	
194	// 11) Atomic critical section (spinlock).
195	//   Uses amoswap.w to atomically swap 1 in and read back the prior value;
196	//   success when prior was 0. Release via amoswap.w with 0.
197	//
198	//   IMPORTANT — SIMD-lockstep gate: this pattern deadlocks within a
199	//   warp on architectures with strict warp-lockstep execution (Vortex,
200	//   pre-Volta CUDA): one thread acquires the lock and diverges into
201	//   the critical section, but the IPDOM stack stalls it until the
202	//   other threads in the warp leave the else-branch spin loop — which
203	//   they can't, because that requires the holder to release.
204	//   The workaround is to serialize at warp granularity: only one thread per warp
205	//   participates in the lock dance. Inter-warp contention still
206	//   exercises the AMO bank fully.
207	//   Final counter = num_active_harts * iters, where num_active_harts =
208	//   num_cores * num_warps (one thread per warp).
209	void kernel_atomic_critical(kernel_arg_t* __UNIFORM__ arg) {
210	  if (vx_thread_id() != 0) return;
211	  auto counter = (int32_t*)arg->shared_addr;
212	  auto lock    = (int32_t*)arg->per_hart_addr;  // [0] is the lock
213	  for (uint32_t i = 0; i < arg->iters; ++i) {
214	    // Acquire: amoswap.w with 1; succeeds when prior == 0.
215	    int32_t prev;
216	    do {
217	      asm volatile ("amoswap.w %0, %2, (%1)"
218	                    : "=r"(prev)
219	                    : "r"(lock), "r"(1)
220	                    : "memory");
221	    } while (prev != 0);
222	
223	    // Critical section: non-atomic increment.
224	    int32_t v = *counter;
225	    *counter = v + 1;
226	
227	    // Release: amoswap.w with 0 (atomicExch in CUDA).
228	    int32_t zero = 0, unused;
229	    asm volatile ("amoswap.w %0, %2, (%1)"
230	                  : "=r"(unused)
231	                  : "r"(lock), "r"(zero)
232	                  : "memory");
233	    (void)unused;
234	  }
235	}
236	
237	// (LR/SC mutex omitted: a spin-lock acquire deadlocks under Vortex's
238	// SIMD-lockstep semantics. Same issue as kernel_atomic_critical but
239	// using LR/SC instead of amoswap; the warp-gated workaround used in
240	// kernel_atomic_critical is also the right way to write it.)
241	
242	// 12) Issuer self-consistency.
243	//   Each hart operates on its OWN private word (no cross-hart sharing):
244	//   a plain load (which caches the line), an atomic +1, then a plain
245	//   load that MUST observe the increment — RISC-V same-hart program
246	//   order requires a hart to see its own prior atomic. The observed
247	//   value is recorded for the host. Fails when a non-LLC cache leaves
248	//   the issuer's cached copy un-invalidated after the AMO (the post-AMO
249	//   load then hits the stale line). Final per_hart[hid] == 1.
250	void kernel_self_consistency(kernel_arg_t* __UNIFORM__ arg) {
251	  uint32_t hid = hart_id();
252	  // Each hart owns a private 64B cache line (no false sharing): shared + hid*64.
253	  volatile uint32_t* p = (volatile uint32_t*)((uint8_t*)arg->shared_addr + (size_t)hid * 64);
254	  uint32_t* per_hart = (uint32_t*)arg->per_hart_addr;
255	  (void)*p;  // plain load: bring this hart's line into the L1
256	  __atomic_fetch_add((uint32_t*)p, 1u, __ATOMIC_SEQ_CST);
257	  per_hart[hid] = *p;  // plain load after the AMO: must observe the +1
258	}
259	
260	static const PFN_Kernel sc_tests[] = {
261	  kernel_amoadd,             // 0
262	  kernel_amoor,              // 1
263	  kernel_amoand,             // 2
264	  kernel_amoxor,             // 3
265	  kernel_amomax,             // 4
266	  kernel_amominu,            // 5
267	  kernel_amoswap,            // 6
268	  kernel_lrsc_counter,       // 7
269	  kernel_amoadd_aqrl,        // 8
270	  kernel_lrsc_counter_aqrl,  // 9
271	  kernel_atomic_reduction,   // 10  CUDA-style reduction
272	  kernel_atomic_critical,    // 11  CUDA-style critical section
273	  kernel_self_consistency,   // 12  issuer self-consistency (load->AMO->load)
274	};
275	
276	__kernel void kernel_main(kernel_arg_t* __UNIFORM__ arg) {
277	  sc_tests[arg->testid](arg);
278	}
