16	// Pure combinational RVA RMW kernel. Given the cache line's current word
17	// at the AMO byte offset and the rs2 operand, derives:
18	//   - new_word: the value to write back for store-bearing AMOs (all except LR).
19	//   - ret_word: the original loaded value, sign-extended into rd.
20	//               For SC the bank overrides this with 0/1 outside this module.
21	// DATA_WIDTH is the synthesized operand width (= the cache word width, capped
22	// at 64): a 32-bit-word cache can only carry .W atomics, so the adder and
23	// comparators are built 32-bit rather than 64-bit. width selects .W vs .D and
24	// is only meaningful when DATA_WIDTH > 32.
25	module VX_amo_alu import VX_gpu_pkg::*; #(
26	    parameter DATA_WIDTH = 64
27	) (
28	    input  amo_op_e     op,
29	    input  wire         is_unsigned, // selects MIN/MAX variant
30	    input  wire [1:0]   width,        // 2 = .W, 3 = .D
31	    input  wire [63:0]  old_word,
32	    input  wire [63:0]  rhs,
33	    output wire [63:0]  new_word,
34	    output wire [63:0]  ret_word
35	);
36	    localparam AW = DATA_WIDTH;
37	
38	    // .W and .D only differ when the datapath is wider than 32 bits;
39	    // a <= 32-bit operand width can only ever be a .W atomic.
40	    wire is_w = (AW > 32) ? (width == 2'd2) : 1'b1;
41	    if (AW <= 32) begin : g_w_only
42	        `UNUSED_VAR (width)
43	    end
44	    if (AW < 64) begin : g_hi_unused
45	        `UNUSED_VAR (old_word[63:AW])
46	        `UNUSED_VAR (rhs[63:AW])
47	    end
48	
49	    wire [AW-1:0] a = old_word[AW-1:0];
50	    wire [AW-1:0] b = rhs[AW-1:0];
51	
52	    // Mask to width-sized values; sign-extend at the 32-bit boundary for MIN/MAX.
53	    wire [AW-1:0] a_u = is_w ? {{(AW-32){1'b0}},  a[31:0]} : a;
54	    wire [AW-1:0] b_u = is_w ? {{(AW-32){1'b0}},  b[31:0]} : b;
55	    wire signed [AW-1:0] a_s = is_w ? {{(AW-32){a[31]}}, a[31:0]} : a;
56	    wire signed [AW-1:0] b_s = is_w ? {{(AW-32){b[31]}}, b[31:0]} : b;
57	
58	    reg [AW-1:0] res;
59	    always @(*) begin
60	        case (op)
61	            AMO_OP_LR:    res = a_u;
62	            AMO_OP_SC:    res = b_u;
63	            AMO_OP_SWAP:  res = b_u;
64	            AMO_OP_ADD:   res = a_u + b_u;
65	            AMO_OP_AND:   res = a_u & b_u;
66	            AMO_OP_OR:    res = a_u | b_u;
67	            AMO_OP_XOR:   res = a_u ^ b_u;
68	            AMO_OP_MIN:   res = is_unsigned ? ((a_u < b_u) ? a_u : b_u)
69	                                            : ((a_s < b_s) ? a_s : b_s);
70	            AMO_OP_MAX:   res = is_unsigned ? ((a_u > b_u) ? a_u : b_u)
71	                                            : ((a_s > b_s) ? a_s : b_s);
72	            default:      res = a_u;
73	        endcase
74	        if (is_w) res = {{(AW-32){1'b0}}, res[31:0]};
75	    end
76	
77	    // Zero-extend the AW-sized results back to the 64-bit port.
78	    // For SC the bank overrides ret_word with 0/1.
79	    assign new_word = 64'(res);
80	    assign ret_word = 64'(is_w ? {{(AW-32){1'b0}}, a[31:0]} : a);
81	
82	endmodule
