37	class ITestCase {
38	public:
39	  ITestCase(TestSuite* suite, const char* name) : suite_(suite), name_(name) {}
40	  virtual ~ITestCase() {}
41	
42	  TestSuite* suite() const { return suite_; }
43	  const char* name() const { return name_; }
44	
45	  // Initialize the shared word and per-hart buffer to test-specific
46	  // initial values. `n` is num_harts (size of per_hart buffer in u32s).
47	  virtual void setup(uint32_t n, uint32_t* shared, uint32_t* per_hart) = 0;
48	
49	  // Validate the post-run shared word and per-hart buffer.
50	  // Returns 0 on pass, error count on fail.
51	  virtual int verify(uint32_t n, uint32_t iters,
52	                     const uint32_t* shared, const uint32_t* per_hart) = 0;
