59	// 0) AMOADD hammer: each hart does +1 iter times. Final = n * iters.
60	class Test_AMOADD : public ITestCase {
61	public:
62	  Test_AMOADD(TestSuite* s) : ITestCase(s, "amoadd") {}
63	  void setup(uint32_t, uint32_t* shared, uint32_t* /*ph*/) override {
64	    *shared = 0;
65	  }
66	  int verify(uint32_t n, uint32_t iters,
67	             const uint32_t* shared, const uint32_t* /*ph*/) override {
68	    uint32_t expected = n * iters;
69	    if (*shared != expected) {
70	      std::cout << "  shared=" << *shared << " expected=" << expected << std::endl;
71	      return 1;
72	    }
73	    return 0;
74	  }
75	};
76	
77	// 1) AMOOR hammer: each hart sets bit (hart_id % 32) idempotently.
78	//    Final = OR of all such bits = 0xFFFFFFFF for n>=32 (all bits 0..31 hit),
79	//    else (1 << n) - 1.
80	class Test_AMOOR : public ITestCase {
81	public:
82	  Test_AMOOR(TestSuite* s) : ITestCase(s, "amoor") {}
83	  void setup(uint32_t, uint32_t* shared, uint32_t*) override { *shared = 0; }
84	  int verify(uint32_t n, uint32_t /*iters*/,
85	             const uint32_t* shared, const uint32_t*) override {
86	    uint32_t expected = 0;
87	    for (uint32_t h = 0; h < n; ++h) expected |= 1u << (h & 31);
88	    if (*shared != expected) {
89	      std::cout << "  shared=0x" << std::hex << *shared
90	                << " expected=0x" << expected << std::dec << std::endl;
91	      return 1;
92	    }
93	    return 0;
94	  }
95	};
