97	// 2) AMOAND hammer: start all-ones, each hart clears bit (hart_id % 32).
98	class Test_AMOAND : public ITestCase {
99	public:
100	  Test_AMOAND(TestSuite* s) : ITestCase(s, "amoand") {}
101	  void setup(uint32_t, uint32_t* shared, uint32_t*) override {
102	    *shared = 0xffffffff;
103	  }
104	  int verify(uint32_t n, uint32_t /*iters*/,
105	             const uint32_t* shared, const uint32_t*) override {
106	    uint32_t cleared = 0;
107	    for (uint32_t h = 0; h < n; ++h) cleared |= 1u << (h & 31);
108	    uint32_t expected = ~cleared;
